package com.slotmind.service;
import com.slotmind.dto.Dtos.*; import com.slotmind.entity.*; import org.springframework.stereotype.Component;
 @Component public class MappingService { public ProviderView provider(Provider p){return new ProviderView(p.getId(),p.getName(),p.getSpecialty(),p.getStatus());} public SlotView slot(Slot s){return new SlotView(s.getId(),s.getProvider().getId(),s.getProvider().getName(),s.getStartTime(),s.getDurationMinutes(),s.getStatus());} public AppointmentView appointment(Appointment a){return new AppointmentView(a.getId(),a.getPatientName(),a.getType(),a.getProvider().getId(),a.getProvider().getName(),a.getSlot().getId(),a.getSlot().getStartTime(),a.getStatus());} public SuggestionView suggestion(RescheduleSuggestion s){return new SuggestionView(s.getId(),s.getAppointment().getId(),s.getAppointment().getPatientName(),s.getOriginalProviderName(),s.getOriginalTime(),s.getRecommendedSlot().getId(),s.getRecommendedSlot().getProvider().getName(),s.getRecommendedSlot().getStartTime(),s.getConfidence(),s.getReasoning(),s.getStatus(),s.getTriggerReason(),s.getSource());} }